/**
 * LocationNames.cpp - Met-location name lookup (per generation)
 *
 * Auto-generated by tools/gen_locations.py from PKHeX's met-location text resources.
 *
 * ONE table set per generation. A HOME-transferred mon keeps its origin id and is named
 * with its ORIGIN generation's table, so a Sun/Moon or Gen 4/5/6 mon in a Gen 9 save is
 * routed to its own table (else it read "(none)"). getMetLocationName dispatches on the
 * origin version byte -> generation table, then banks by id:
 *   Gen 3      bank 0 only.
 *   Gen 4      bank 0 / 2000 / 3000            (id - base).
 *   Gen 5+     bank 0 / 30000 / 40000 / 60000  (id - base).
 * Mirrors PKHeX LocationSet{0,4,6}.GetLocationName.
 *
 * Blank slots and PKHeX's em-dash "no location" sentinel are emitted as "".
 */

#include "Names/LocationNames.h"

#include <cstddef>
