    // Legends: Z-A (ZA=52) -- bank 6  [ids 60000+]
    // Source: PKHeX text_za_60000_en.txt  (6 entries)
    static const char* const ZA_LOC_NAMES_6[] = {
        "",  // 60000
        "someone far away",  // 60001
        "a Nursery worker",  // 60002
        "a treasure hunter",  // 60003
        "an old hot-springs visitor",  // 60004
        "Lumiose City",  // 60005
    };

    // names[id] when in range, else "" (also "" for an absent bank: table=nullptr, count=0).
    static const char* lookup(const char* const* table, size_t count, uint16_t id) {
        return (table && id < count) ? table[id] : "";
    }

    // LocationSet6 banking (Gen 5+): id / 10000 selects the bank.
    static const char* lookupBanked(
            const char* const* b0, size_t n0, const char* const* b3, size_t n3,
            const char* const* b4, size_t n4, const char* const* b6, size_t n6, uint16_t id) {
        if (id >= 60000) return lookup(b6, n6, static_cast<uint16_t>(id - 60000));
        if (id >= 40000) return lookup(b4, n4, static_cast<uint16_t>(id - 40000));
        if (id >= 30000) return lookup(b3, n3, static_cast<uint16_t>(id - 30000));
        return lookup(b0, n0, id);
    }

    // LocationSet4 banking (Gen 4): banks at 0 / 2000 / 3000.
    static const char* lookupBanked4(
            const char* const* b0, size_t n0, const char* const* b2, size_t n2,
            const char* const* b3, size_t n3, uint16_t id) {
        if (id >= 3000) return lookup(b3, n3, static_cast<uint16_t>(id - 3000));
        if (id >= 2000) return lookup(b2, n2, static_cast<uint16_t>(id - 2000));
        return lookup(b0, n0, id);
    }

    const char* getMetLocationName(uint8_t originVersion, uint16_t locationId) {
        switch (originVersion) {
            case 1: case 2: case 3: case 4: case 5:
                return lookup(G3_LOC_NAMES, sizeof(G3_LOC_NAMES) / sizeof(G3_LOC_NAMES[0]), locationId);
            case 7: case 8: case 10: case 11: case 12:
                return lookupBanked4(G4_LOC_NAMES, sizeof(G4_LOC_NAMES) / sizeof(G4_LOC_NAMES[0]), G4_LOC_NAMES_2, sizeof(G4_LOC_NAMES_2) / sizeof(G4_LOC_NAMES_2[0]), G4_LOC_NAMES_3, sizeof(G4_LOC_NAMES_3) / sizeof(G4_LOC_NAMES_3[0]), locationId);
            case 20: case 21: case 22: case 23:
                return lookupBanked(G5_LOC_NAMES, sizeof(G5_LOC_NAMES) / sizeof(G5_LOC_NAMES[0]), G5_LOC_NAMES_3, sizeof(G5_LOC_NAMES_3) / sizeof(G5_LOC_NAMES_3[0]), G5_LOC_NAMES_4, sizeof(G5_LOC_NAMES_4) / sizeof(G5_LOC_NAMES_4[0]), G5_LOC_NAMES_6, sizeof(G5_LOC_NAMES_6) / sizeof(G5_LOC_NAMES_6[0]), locationId);
            case 24: case 25: case 26: case 27:
                return lookupBanked(G6_LOC_NAMES, sizeof(G6_LOC_NAMES) / sizeof(G6_LOC_NAMES[0]), G6_LOC_NAMES_3, sizeof(G6_LOC_NAMES_3) / sizeof(G6_LOC_NAMES_3[0]), G6_LOC_NAMES_4, sizeof(G6_LOC_NAMES_4) / sizeof(G6_LOC_NAMES_4[0]), G6_LOC_NAMES_6, sizeof(G6_LOC_NAMES_6) / sizeof(G6_LOC_NAMES_6[0]), locationId);
            case 30: case 31: case 32: case 33:
                return lookupBanked(G7_LOC_NAMES, sizeof(G7_LOC_NAMES) / sizeof(G7_LOC_NAMES[0]), G7_LOC_NAMES_3, sizeof(G7_LOC_NAMES_3) / sizeof(G7_LOC_NAMES_3[0]), G7_LOC_NAMES_4, sizeof(G7_LOC_NAMES_4) / sizeof(G7_LOC_NAMES_4[0]), G7_LOC_NAMES_6, sizeof(G7_LOC_NAMES_6) / sizeof(G7_LOC_NAMES_6[0]), locationId);
            case 34: case 42: case 43:
                return lookupBanked(GG_LOC_NAMES, sizeof(GG_LOC_NAMES) / sizeof(GG_LOC_NAMES[0]), nullptr, 0, GG_LOC_NAMES_4, sizeof(GG_LOC_NAMES_4) / sizeof(GG_LOC_NAMES_4[0]), nullptr, 0, locationId);
            case 44: case 45:
                return lookupBanked(SWSH_LOC_NAMES, sizeof(SWSH_LOC_NAMES) / sizeof(SWSH_LOC_NAMES[0]), SWSH_LOC_NAMES_3, sizeof(SWSH_LOC_NAMES_3) / sizeof(SWSH_LOC_NAMES_3[0]), SWSH_LOC_NAMES_4, sizeof(SWSH_LOC_NAMES_4) / sizeof(SWSH_LOC_NAMES_4[0]), SWSH_LOC_NAMES_6, sizeof(SWSH_LOC_NAMES_6) / sizeof(SWSH_LOC_NAMES_6[0]), locationId);
            case 47:
                return lookupBanked(PLA_LOC_NAMES, sizeof(PLA_LOC_NAMES) / sizeof(PLA_LOC_NAMES[0]), PLA_LOC_NAMES_3, sizeof(PLA_LOC_NAMES_3) / sizeof(PLA_LOC_NAMES_3[0]), PLA_LOC_NAMES_4, sizeof(PLA_LOC_NAMES_4) / sizeof(PLA_LOC_NAMES_4[0]), PLA_LOC_NAMES_6, sizeof(PLA_LOC_NAMES_6) / sizeof(PLA_LOC_NAMES_6[0]), locationId);
            case 48: case 49:
                return lookupBanked(BDSP_LOC_NAMES, sizeof(BDSP_LOC_NAMES) / sizeof(BDSP_LOC_NAMES[0]), BDSP_LOC_NAMES_3, sizeof(BDSP_LOC_NAMES_3) / sizeof(BDSP_LOC_NAMES_3[0]), BDSP_LOC_NAMES_4, sizeof(BDSP_LOC_NAMES_4) / sizeof(BDSP_LOC_NAMES_4[0]), BDSP_LOC_NAMES_6, sizeof(BDSP_LOC_NAMES_6) / sizeof(BDSP_LOC_NAMES_6[0]), locationId);
            case 50: case 51:
                return lookupBanked(SV_LOC_NAMES, sizeof(SV_LOC_NAMES) / sizeof(SV_LOC_NAMES[0]), SV_LOC_NAMES_3, sizeof(SV_LOC_NAMES_3) / sizeof(SV_LOC_NAMES_3[0]), SV_LOC_NAMES_4, sizeof(SV_LOC_NAMES_4) / sizeof(SV_LOC_NAMES_4[0]), SV_LOC_NAMES_6, sizeof(SV_LOC_NAMES_6) / sizeof(SV_LOC_NAMES_6[0]), locationId);
            case 52:
                return lookupBanked(ZA_LOC_NAMES, sizeof(ZA_LOC_NAMES) / sizeof(ZA_LOC_NAMES[0]), ZA_LOC_NAMES_3, sizeof(ZA_LOC_NAMES_3) / sizeof(ZA_LOC_NAMES_3[0]), ZA_LOC_NAMES_4, sizeof(ZA_LOC_NAMES_4) / sizeof(ZA_LOC_NAMES_4[0]), ZA_LOC_NAMES_6, sizeof(ZA_LOC_NAMES_6) / sizeof(ZA_LOC_NAMES_6[0]), locationId);
            default:
                return "";
        }
    }

    // Raw bank-0 (in-world) name table for an origin, so a picker can enumerate the
    // user-assignable met locations. The special banks are trade/transfer/egg markers.
    LocationTable getLocationTable(uint8_t originVersion) {
        switch (originVersion) {
            case 1: case 2: case 3: case 4: case 5:
                return { G3_LOC_NAMES, sizeof(G3_LOC_NAMES) / sizeof(G3_LOC_NAMES[0]) };
            case 7: case 8: case 10: case 11: case 12:
                return { G4_LOC_NAMES, sizeof(G4_LOC_NAMES) / sizeof(G4_LOC_NAMES[0]) };
            case 20: case 21: case 22: case 23:
                return { G5_LOC_NAMES, sizeof(G5_LOC_NAMES) / sizeof(G5_LOC_NAMES[0]) };
            case 24: case 25: case 26: case 27:
                return { G6_LOC_NAMES, sizeof(G6_LOC_NAMES) / sizeof(G6_LOC_NAMES[0]) };
            case 30: case 31: case 32: case 33:
                return { G7_LOC_NAMES, sizeof(G7_LOC_NAMES) / sizeof(G7_LOC_NAMES[0]) };
            case 34: case 42: case 43:
                return { GG_LOC_NAMES, sizeof(GG_LOC_NAMES) / sizeof(GG_LOC_NAMES[0]) };
            case 44: case 45:
                return { SWSH_LOC_NAMES, sizeof(SWSH_LOC_NAMES) / sizeof(SWSH_LOC_NAMES[0]) };
            case 47:
                return { PLA_LOC_NAMES, sizeof(PLA_LOC_NAMES) / sizeof(PLA_LOC_NAMES[0]) };
            case 48: case 49:
                return { BDSP_LOC_NAMES, sizeof(BDSP_LOC_NAMES) / sizeof(BDSP_LOC_NAMES[0]) };
            case 50: case 51:
                return { SV_LOC_NAMES, sizeof(SV_LOC_NAMES) / sizeof(SV_LOC_NAMES[0]) };
            case 52:
                return { ZA_LOC_NAMES, sizeof(ZA_LOC_NAMES) / sizeof(ZA_LOC_NAMES[0]) };
            default:
                return { nullptr, 0 };
        }
    }
